    assert_eq!(solve(3, 2, "123-45".chars().collect()), vec!['Y','e','s']);
    assert_eq!(solve(3, 2, "12-345".chars().collect()), vec!['N','o']); // hyphen at pos 2, not 3
    assert_eq!(solve(1, 1, "1-2".chars().collect()), vec!['Y','e','s']);
